-- Additive only. Explicitly targets the pre-existing isolated berahost schema.
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM information_schema.schemata WHERE schema_name='berahost') THEN RAISE EXCEPTION 'Required isolated schema berahost is missing; create/provision it out of band before applying this migration'; END IF; END $$;
CREATE TABLE berahost.referral_program(id integer PRIMARY KEY DEFAULT 1 CHECK(id=1), enabled boolean NOT NULL DEFAULT true, referrals_required integer NOT NULL DEFAULT 3 CHECK(referrals_required>0), reward_plan varchar(20) NOT NULL DEFAULT 'starter' CHECK(reward_plan IN('starter','silver','gold')), reward_duration_days integer NOT NULL DEFAULT 30 CHECK(reward_duration_days>0), updated_by integer, updated_at timestamptz NOT NULL DEFAULT now());
INSERT INTO berahost.referral_program DEFAULT VALUES ON CONFLICT DO NOTHING;
CREATE TABLE berahost.referral_qualifications(referred_id integer PRIMARY KEY REFERENCES berahost.users(id), referrer_id integer NOT NULL REFERENCES berahost.users(id), qualified_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX referral_qualifications_referrer_idx ON berahost.referral_qualifications(referrer_id);
CREATE TABLE berahost.referral_rewards(id serial PRIMARY KEY, referrer_id integer NOT NULL REFERENCES berahost.users(id), plan varchar(20) NOT NULL CHECK(plan IN('starter','silver','gold')), duration_days integer NOT NULL CHECK(duration_days>0), status varchar(20) NOT NULL DEFAULT 'available' CHECK(status IN('available','claimed')), created_at timestamptz NOT NULL DEFAULT now(), claimed_at timestamptz, expires_at timestamptz);
CREATE INDEX referral_rewards_owner_idx ON berahost.referral_rewards(referrer_id,id);
CREATE TABLE berahost.redeem_codes(id serial PRIMARY KEY, code_hash varchar(64) NOT NULL UNIQUE CHECK(code_hash ~ '^[0-9a-f]{64}$'), plan varchar(20) NOT NULL CHECK(plan IN('starter','silver','gold')), duration_days integer NOT NULL CHECK(duration_days>0), max_redemptions integer CHECK(max_redemptions IS NULL OR max_redemptions>0), expires_at timestamptz, label varchar(200), status varchar(20) NOT NULL DEFAULT 'active' CHECK(status IN('active','paused','revoked')), created_by integer NOT NULL REFERENCES berahost.users(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE berahost.redeem_code_redemptions(id serial PRIMARY KEY, code_id integer NOT NULL REFERENCES berahost.redeem_codes(id), user_id integer NOT NULL REFERENCES berahost.users(id), plan varchar(20) NOT NULL, duration_days integer NOT NULL, expires_at timestamptz NOT NULL, redeemed_at timestamptz NOT NULL DEFAULT now(), UNIQUE(code_id,user_id));
CREATE TABLE berahost.referral_program_audit(id serial PRIMARY KEY, admin_id integer NOT NULL REFERENCES berahost.users(id), action varchar(40) NOT NULL, details text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
